  "dashboard.indicator.backtest.executionAssumptions.aggressiveFallback": "Der aggressive Modus ist aktiviert, aber die Simulation von Unterbalken im 1-Minuten-Bereich war nicht verfügbar – daher wurde auf den Standard-Schlusskurs desselben Balkens zurückgegriffen.",
  "dashboard.indicator.backtest.executionAssumptions.bodyAggressive1m": "Aggressiv (Krypto): Signale auf demselben Balken im Strategie-TF {sig}, ausgeführt innerhalb von {exec} Balken (≈10 Sekunden Live-Abfrage). Stop-Loss/Take-Profit können auf Unterbalken früher ausgelöst werden.",
  "dashboard.indicator.backtest.executionAssumptions.bodyAggressiveBar": "Aggressiv: Bestätigung und Ausführung zum Schlusskurs desselben Balkens (plus Slippage). Üblicherweise optimistischer als der strikte Modus.",
  "dashboard.indicator.backtest.executionAssumptions.bodyMtf": "Pfad mit mehreren Zeitrahmen: Signalzeitrahmen {sig}, Ausführungszeitrahmen {exec}.",
  "dashboard.indicator.backtest.executionAssumptions.bodyNextBar": "Sobald das Signal zum Schlusskurs eines Balkens bestätigt wurde, erfolgt die Ausführung zum Eröffnungskurs des nächsten Balkens (zuzüglich Slippage). Die Handelszeitstempel sind oft um einen Balken gegenüber den Markierungen im Chart verschoben.",
  "dashboard.indicator.backtest.executionAssumptions.bodySameBar": "Sobald das Signal beim Schlusskurs eines Balkens bestätigt ist, werden die Positionen zum Schlusskurs dieses Balkens (zuzüglich Slippage) ausgeführt. Die Zeitstempel stimmen mit den Chartmarkierungen überein; die Ergebnisse sind in der Regel optimistischer.",
  "dashboard.indicator.backtest.executionAssumptions.bodyScriptStandard": "Skript-Strategie-Backtest: handle_data läuft auf jeder geschlossenen Leiste im Strategie-Zeitrahmen; Bestellungen aus dem Rezept werden standardmäßig an der nächsten Bar ausgefüllt, die geöffnet ist (plus Verschiebung/Gebühren). Dies ist nicht der Indikator-Umschalter für strikte/nicht-strenge Schalter – es ist der Standard-Skript-Wiederholungspfad.",
  "dashboard.indicator.backtest.executionAssumptions.bodyStrict": "Strenger Modus: Signale nur bei geschlossenen Balken, Ausführung beim nächsten offenen Balken (plus Slippage). Spiele laufen im strengen Modus – konservativ, aber realistischer.",
  "dashboard.indicator.backtest.executionAssumptions.colCommission": "Kommission",
  "dashboard.indicator.backtest.executionAssumptions.colMode": "Simulation",
  "dashboard.indicator.backtest.executionAssumptions.colSlippage": "Schlupf",
  "dashboard.indicator.backtest.executionAssumptions.colTiming": "Signalzeitpunkt",
  "dashboard.indicator.backtest.executionAssumptions.fallbackData": "Konnte keine detaillierten Kerzen abrufen – bin auf den Standard-Backtest zurückgegriffen.",
  "dashboard.indicator.backtest.executionAssumptions.fallbackNoGain": "Der Strategiezeitraum ist nicht gröber als der Ausführungszeitraum – kein MTF-Gewinn bei Verwendung eines Standard-Backtests.",
  "dashboard.indicator.backtest.executionAssumptions.fallbackRange": "Der Datumsbereich überschreitet die Grenze für hohe Präzision – daher wurde auf Standard-Backtest zurückgegriffen.",
  "dashboard.indicator.backtest.executionAssumptions.fallbackScale": "Scale-in/Scale-out-Regeln sind aktiviert – MTF ist nicht verfügbar, Standard-Backtest wird verwendet.",
  "dashboard.indicator.backtest.executionAssumptions.fallbackTiming": "Die aktuelle Einstellung für die Füllzeit wird in MTF nicht unterstützt – dies wird durch einen Standard-Backtest bestätigt.",
  "dashboard.indicator.backtest.executionAssumptions.fallbackUnavailable": "Hochpräziser Backtest nicht verfügbar – daher wurde auf Standard-Backtest zurückgegriffen.",
  "dashboard.indicator.backtest.executionAssumptions.fillClose": "Standard-Füllreferenz: Schlusskurs.",
  "dashboard.indicator.backtest.executionAssumptions.fillOpen": "Standard-Füllreferenz: Eröffnungskurs.",
  "dashboard.indicator.backtest.executionAssumptions.legacyBody": "Dieser Lauf wurde gespeichert, bevor Ausführungsmetadaten verfügbar waren. Ältere Läufe gehen typischerweise davon aus, dass die Positionen beim Öffnen des nächsten Balkens nach dem Schließen des Signalbalkens gefüllt werden. Führen Sie den Lauf mit der Option „Gleicher Balkenschluss“ erneut aus, wenn Sie chartkonforme Zeitstempel benötigen.",
  "dashboard.indicator.backtest.executionAssumptions.legacyTitle": "Über diesen gespeicherten Lauf",
  "dashboard.indicator.backtest.executionAssumptions.modeAggressive1m": "Aggressiv · 1m Unterbalken ({exec})",
  "dashboard.indicator.backtest.executionAssumptions.modeAggressiveBar": "Aggressiv · Standardbalken",
  "dashboard.indicator.backtest.executionAssumptions.modeScriptStandard": "Standard-Skript · Taktweise · Nächste-Takt-Offenfüllung",
  "dashboard.indicator.backtest.executionAssumptions.modeStrict": "Streng (Strategie TF)",
  "dashboard.indicator.backtest.executionAssumptions.mtfFallback": "Es wurde keine hochpräzise Simulation über mehrere Zeitrahmen hinweg durchgeführt (dafür wurde auf Standard-Backtests zurückgegriffen); siehe oben stehenden Hinweis zur Präzision.",
  "dashboard.indicator.backtest.executionAssumptions.mtfOffByUser": "Hochpräzise MTF ist deaktiviert – Standard-OHLC-Backtest mit einem einzigen Zeitrahmen.",
  "dashboard.indicator.backtest.executionAssumptions.scriptStandardShort": "Script-Std",
  "dashboard.indicator.backtest.executionAssumptions.strictModeOffNote": "Spiele werden live übertragen, wenn der strikte Modus deaktiviert ist: Intra-Bar-Signale können ausgelöst werden – Backtest sieht oft besser aus als live.",
  "dashboard.indicator.backtest.executionAssumptions.strictModeOnNote": "Die Spiele werden im strikten Modus gespielt: Nur geschlossene Balkensignale – entspricht am ehesten den Annahmen des Backtests.",
  "dashboard.indicator.backtest.executionAssumptions.timingNextBar": "Die nächste Bar ist geöffnet",
  "dashboard.indicator.backtest.executionAssumptions.timingSameBar": "Gleiche Bar schließt",
  "dashboard.indicator.backtest.executionAssumptions.timingScriptNextBar": "Taktweise · nächster Takt offen füllen",
  "dashboard.indicator.backtest.executionAssumptions.title": "Ausführungsannahmen",
  "dashboard.indicator.backtest.executionAssumptions.tradeCountMtfNote": "Kauf-/Verkaufssignale im Strategie-Zeitrahmen bleiben unverändert. MTF kann Stop-/Take-Profit-Orders auf feineren Balken auslösen, wodurch sich der Ausstiegszeitpunkt und mitunter die Anzahl der Trades im Vergleich zum Standard-Backtest ändert.",
  "dashboard.indicator.backtest.executionAssumptions.tradeCountScriptNote": "Das Skript spielt Backtests von Balken zu Balken ab; die Anzahl der Trades richtet sich nach den Skriptaufträgen zuzüglich der Ausführungsregeln der Plattform (Standard: Eröffnung des nächsten Balkens).",
  "dashboard.indicator.backtest.executionAssumptions.tradeCountStandardNote": "Die Anzahl der Signale ist durch Ihren Zeitrahmen festgelegt. Bei gleicher Engine sollte die Anzahl der Trades bei Live-Trading im Vergleich zu explorativem Trading (nur Gebühren/Slippage) gleich sein; der Gewinn/Verlust unterscheidet sich jedoch.",
