  "dashboard.indicator.error.tiingoSubscription": "Für Forex-Daten im 1-Minuten-Takt ist ein kostenpflichtiges Tiingo-Abonnement erforderlich. Bitte verwenden Sie andere Zeitrahmen oder erweitern Sie Ihr Abonnement.",
