  "fastAnalysis.indicatorsProSubtitle": "Ausgerichtet auf das Backend `MarketDataCollector._calculate_indicators` (Mainstream-Stil): Der RSI(14) ist Wilder-geglättet. Der MACD(12,26,9) verwendet SMA-basierte EMAs auf Basis der Schlusskurse; DIF ab Balken 26; DEA = EMA9 der DIF-Serie (ca. 34+ Balken für eine vollständige Signallinie). Die gleitenden Durchschnitte sind SMAs. Der Pivotpunkt verwendet die Hoch-/Tief-/Kontinuumspunkte des vorherigen Balkens. Swing = 20-Bar-Hoch-/Tiefstwerte. Bollinger = SMA(20) ± 2×Populations-σ; aggregierte Niveaus verwenden BB_upper/BB_lower. Der ATR(14) ist Wilder und wird an den letzten Balken gekoppelt. Siehe docs/INDICATOR_DEFINITIONS_CN.md für Volumenverhältnis und Bereichsposition.",
