  "profile.agentTokens.intro": "Stellen Sie ein Agenten-Token aus, damit Cursor-/Claude-Code-/MCP-Clients die API-Schnittstelle /api/agent/v1 für Ihr Konto aufrufen können. Das vollständige Token wird nur einmal angezeigt – bewahren Sie es sicher auf.",
