  "user.login.infos": "QuantDinger ist ein KI-gestütztes Aktienanalysetool, das keine Wertpapierberatung anbietet. Alle Analyseergebnisse, Bewertungen und Empfehlungen auf der Plattform werden automatisch von der KI auf Basis historischer Daten generiert und dienen ausschließlich Lern-, Forschungs- und Fachzwecken. Sie stellen keine Anlageberatung oder Entscheidungsgrundlage dar. Aktieninvestitionen bergen Markt-, Liquiditäts-, Politik- und weitere Risiken, die zu Kapitalverlusten führen können. Nutzer sollten ihre Anlageentscheidungen eigenständig und unter Berücksichtigung ihrer Risikotoleranz treffen und die Konsequenzen ihres Handelns und dessen Ergebnisse selbst tragen. Bei der Nutzung dieses Tools ist Vorsicht geboten.",
