  "user.login.legal.collapse": "Rechtlichen Hinweis ausblenden",
  "user.login.legal.content": "QuantDinger ist ein KI-gestütztes Aktienanalysetool und bietet keine Anlageberatung. Alle Analyseergebnisse, Bewertungen und Referenzen werden von der KI auf Basis historischer Daten generiert und dienen ausschließlich Lern-, Forschungs- und Fachgesprächszwecken. Sie stellen keine Anlageberatung dar und sind keine Grundlage für Anlageentscheidungen. Aktienanlagen bergen Markt-, Liquiditäts- und politische Risiken, die zum Verlust des eingesetzten Kapitals führen können. Nutzer sollten ihre Anlageentscheidungen eigenständig und unter Berücksichtigung ihrer Risikotoleranz treffen und die Konsequenzen ihres Anlageverhaltens und der Ergebnisse, die sie mit diesem Tool erzielen, selbst tragen.",
