  "user.login.privacy.collapse": "Datenschutzrichtlinie ausblenden",
  "user.login.privacy.content": "Wir legen Wert auf Ihre Privatsphäre und den Schutz Ihrer Daten. (1) Umfang der Datenerhebung: Wir erheben nur die für die Bereitstellung des Dienstes notwendigen Informationen (z. B. E-Mail-Adresse, Mobiltelefonnummer, Ländervorwahl, Web3-Wallet-Adresse) sowie eingeschränkte Protokoll-/Gerätedaten. (2) Verwendungszweck: Kontoanmeldung und Sicherheitsverifizierung, Bereitstellung von Funktionen, Fehlerbehebung und Einhaltung gesetzlicher Bestimmungen. (3) Speicherung und Sicherheit: Daten werden verschlüsselt und zugriffskontrolliert, um unbefugten Zugriff, Offenlegung oder Verlust zu verhindern. (4) Weitergabe an Dritte: Wir geben personenbezogene Daten nicht an Dritte weiter, außer wenn dies gesetzlich vorgeschrieben ist oder zur Erbringung des Dienstes erforderlich ist. Bei der Nutzung von Diensten Dritter (z. B. Wallets, SMS-Anbieter) beschränkt sich die Verarbeitung auf das erforderliche Minimum. (5) Cookies/Lokaler Speicher: Werden für Sitzungs- und Anmeldestatus verwendet (z. B. Tokens, PHPSESSID). Sie können diese in Ihrem Browser löschen oder einschränken. (6) Ihre Rechte: Sie können Ihre Rechte auf Auskunft, Berichtigung, Löschung und Widerruf der Einwilligung im gesetzlich zulässigen Rahmen ausüben. (7) Änderungen und Hinweise: Wir werden Sie deutlich über Aktualisierungen informieren. Durch die weitere Nutzung bestätigen Sie, dass Sie die aktualisierten Nutzungsbedingungen gelesen und akzeptiert haben. Sollten Sie nicht einverstanden sein, stellen Sie die Nutzung des Dienstes bitte ein und kontaktieren Sie uns.",
